-- The legacy PIN peppers were historically shipped in the public client.
-- Do not copy their values into this migration or Edge Function source.
-- Provision these two Vault secrets in each isolated environment using the legacy
-- values from the historical client only as a one-time compatibility bridge:
--   student_affairs_legacy_app_pepper
--   student_affairs_legacy_sha_pepper
-- The new verifier pepper remains separately generated by the first migration.
create or replace function public.student_affairs_get_legacy_pin_peppers()
returns jsonb
language sql
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'pbkdf2', (select decrypted_secret from vault.decrypted_secrets where name = 'student_affairs_legacy_app_pepper' limit 1),
    'sha256', (select decrypted_secret from vault.decrypted_secrets where name = 'student_affairs_legacy_sha_pepper' limit 1)
  )
$$;
revoke all on function public.student_affairs_get_legacy_pin_peppers() from public, anon, authenticated;
grant execute on function public.student_affairs_get_legacy_pin_peppers() to service_role;
